    lx=np.log(x)
    if model=='lognormal':
        def obj(p):
            mu,ls=p; sig=np.exp(ls); z=(lx-mu)/sig
            ll=-lx-ls-.5*z*z-.5*np.log(2*np.pi)-stats.norm.logsf((np.log(lower)-mu)/sig)
            return -np.dot(weights,ll)/weights.sum()
        start=[np.average(lx,weights=weights),np.log(np.sqrt(np.average((lx-np.average(lx,weights=weights))**2,weights=weights)))]
    else:
        def obj(p):
            k,scale=np.exp(p)
            z=k*(lx-np.log(scale))
            ll=np.log(k)-np.log(scale)+(k-1)*(lx-np.log(scale))-np.exp(np.clip(z,-700,700))+(lower/scale)**k
            return -np.dot(weights,ll)/weights.sum()
        start=np.log([2.,np.average(x,weights=weights)])
